// Same-origin proxy routes to the three backend services. Tokens stay in memory.
let tokens=null,refreshing=null;
export class ApiError extends Error{constructor(message,status){super(message);this.status=status}}
async function request(path,{method='GET',body,auth=true,retry=true}={}){let response;try{response=await fetch(path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(auth&&tokens?{Authorization:`Bearer ${tokens.accessToken}`}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)})}catch{throw new ApiError('Сервис недоступен или не ответил вовремя. Проверьте подключение. Перед повторной отправкой проверьте «Мои заявки».',0)}if(response.status===401&&auth&&retry&&tokens?.refreshToken){try{refreshing??=request('/api/v0/auth/refresh',{method:'POST',body:{refreshToken:tokens.refreshToken},auth:false,retry:false});tokens=await refreshing;return await request(path,{method,body,auth,retry:false})}catch{tokens=null;throw new ApiError('Сессия завершена. Войдите снова.',401)}finally{refreshing=null}}const data=response.status===204?null:await response.json().catch(()=>null);if(!response.ok){if(response.status===401&&auth)tokens=null;throw new ApiError(data?.message||data?.error||`Ошибка сервера (${response.status})`,response.status)}return data}
export function normalizeProduct(p){return {...p,name:p.title,description:p.purposes,rate:p.interest,min:p.minSum,max:p.maxSum,minMonths:p.minDurationYear*12,maxMonths:p.maxDurationYear*12,kind:p.repaymentTypes?.includes('EQUAL_TOTAL_PARTS')?'annuity':'differentiated'}}
export function normalizeApplication(a){return {...a,productName:a.productTitle||'Индивидуальные условия',requested:{amount:a.amount,months:a.durationYears*12},decision:{status:({ACCEPTED:'approved',REJECTED:'declined',COUNTER_OFFER:'counteroffer',UNDER_CONSIDERATION:'pending'})[a.status]||'pending',amount:a.counterOffer?.amount??a.amount,months:(a.counterOffer?.durationYears??a.durationYears)*12,rate:a.counterOffer?.rate??a.rate,reason:a.decisionComment||'Заявка принята. Ожидайте результат рассмотрения.'}}}
export const api={isAuthenticated:()=>!!tokens,
 async login(login,password){tokens=await request('/api/v0/auth/login',{method:'POST',auth:false,body:{login,password}})},
 async register(data){tokens=await request('/api/v0/auth/register',{method:'POST',auth:false,body:data})},
 async logout(){try{await request('/api/v0/auth/logout',{method:'POST'})}finally{tokens=null}},
 async getProfile(){if(!tokens)return null;const p=await request('/api/v0/users/me');return {...p,name:`${({OOO:'ООО',IP:'ИП',AO:'АО'})[p.organizationType]} · ${p.firstName} ${p.lastName}`,legalForm:({OOO:'ООО',IP:'ИП',AO:'АО'})[p.organizationType],ageMonths:Math.max(0,Math.floor((Date.now()-new Date(p.registrationDate).getTime())/2629800000)),collateralAvailable:true}},
 async getProducts(){const data=await request('/products',{auth:false});return data.products.map(normalizeProduct)},
 async listApplications(){return (await request('/api/v0/applications')).map(normalizeApplication)},
 async getApplication(id){return normalizeApplication(await request('/api/v0/applications/'+encodeURIComponent(id)))},
 async respond(id,accept){return normalizeApplication(await request(`/api/v0/applications/${encodeURIComponent(id)}/counter-offer`,{method:'POST',body:{accept}}))},
 async submitApplication(input){const p=await this.getProfile();if(!p)throw new ApiError('Войдите для отправки заявки',401);return normalizeApplication(await request('/api/v0/applications',{method:'POST',body:{productId:Number(input.productId),calculator:{amount:input.amount,durationYears:input.months/12,organizationType:p.organizationType,collateral:input.collateral,purpose:input.purpose}}}))}
};
